(function (thisObj) {

function buildUI(thisObj){

    var win = (thisObj instanceof Window)
        ? thisObj
        : new Window("palette", "Glitch Reveal Script Shivam", undefined, {resizeable:true});

    win.orientation = "column";
    win.alignChildren = ["fill","top"];
    win.spacing = 12;
    win.margins = 14;

    // =========================
    // HEADER
    // =========================
    
    var subtitle = win.add("statictext", undefined, "Select Single Layer");
    subtitle.enabled = false;

    // =========================
    // SETTINGS PANEL
    // =========================
    var panel = win.add("panel", undefined, "Settings");
    panel.orientation = "column";
    panel.alignChildren = "fill";
    panel.spacing = 10;
    panel.margins = 10;

    // -------------------------
    // Direction
    // -------------------------
    var row1 = panel.add("group");
    row1.add("statictext", undefined, "Direction:");

    var direction = row1.add("dropdownlist", undefined, [
        "Left to Right",
        "Right to Left",
        "Top to Bottom",
        "Bottom to Top",
        "Outward"
    ]);
    direction.selection = 0;
    direction.preferredSize.width = 160;

    // -------------------------
    // SHAPE OPTIONS (NEW)
    // -------------------------
    var row2 = panel.add("group");
    row2.add("statictext", undefined, "Shape:");

    var shapeType = row2.add("dropdownlist", undefined, [
        "Rectangle",
        "Circle",
    ]);
    shapeType.selection = 0;
    shapeType.preferredSize.width = 160;

    // =========================
    // BUTTON
    // =========================
    var btn = win.add("button", undefined, "GENERATE");
    btn.preferredSize.height = 40;
    btn.graphics.font = ScriptUI.newFont("Arial", "BOLD", 14);

    // =========================
    // PROGRESS BAR (NEW)
    // =========================
    var progressGroup = win.add("panel", undefined, "Progress");
    progressGroup.orientation = "column";
    progressGroup.alignChildren = "fill";
    progressGroup.margins = 10;

    var progressBar = progressGroup.add("progressbar", undefined, 0, 100);
    progressBar.preferredSize.height = 14;

    var progressText = progressGroup.add("statictext", undefined, "Waiting...");

    function setProgress(value, text){
        progressBar.value = value;
        progressText.text = text;
        win.update();
    }

    // =========================
    // RESIZE
    // =========================
    win.onResizing = win.onResize = function(){
        this.layout.resize();
    };
    // =========================
    // GLOBAL FUNCTION
    // =========================
    
    //BASE DECODE
    
        function base64Decode(input) {
                var keyStr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
                var output = "";
                var chr1, chr2, chr3;
                var enc1, enc2, enc3, enc4;
                var i = 0;

                input = input.replace(/[^A-Za-z0-9\+\/\=]/g, "");

                while (i < input.length) {
                    enc1 = keyStr.indexOf(input.charAt(i++));
                    enc2 = keyStr.indexOf(input.charAt(i++));
                    enc3 = keyStr.indexOf(input.charAt(i++));
                    enc4 = keyStr.indexOf(input.charAt(i++));

                    chr1 = (enc1 << 2) | (enc2 >> 4);
                    chr2 = ((enc2 & 15) << 4) | (enc3 >> 2);
                    chr3 = ((enc3 & 3) << 6) | enc4;

                    output += String.fromCharCode(chr1);
                    if (enc3 != 64) output += String.fromCharCode(chr2);
                    if (enc4 != 64) output += String.fromCharCode(chr3);
                }

                return output;
            }


    // =========================
    // MAIN ACTION
    // =========================
    btn.onClick = function(){

        app.beginUndoGroup("Reveal System");

        var comp = app.project.activeItem;

        if(!comp || !(comp instanceof CompItem)){
            setProgress(0, "❌ Select a comp");
            app.endUndoGroup();
            return;
        }

        if(comp.selectedLayers.length === 0){
            setProgress(0, "❌ Select a layer");
            app.endUndoGroup();
            return;
        }

        if(comp.selectedLayers.length > 1){
            setProgress(0, "❌ Select only 1 layer at a Time");
            app.endUndoGroup();
            return;
        }

        var layer = comp.selectedLayers[0];
            var layerName = layer.name;
            var statusText = null;
            var layerStartTime = layer.startTime;
            var folder = app.project.items.addFolder(layer.name+"Reveal Precomps");


        // ======================================================================================================================================================
        // STEP 1
        // ======================================================================================================================================================
        statusText = layerName+" : Reading layer...";
        setProgress(10,statusText);
        $.sleep(300);




        // ======================================================================================================================================================
        // STEP 2 PRECOMP
        // ======================================================================================================================================================
        statusText = layerName+" : Creating precomp...";
        setProgress(15,statusText);
        $.sleep(300);

        var layer_obj_precomp = comp.layers.precompose([layer.index],layer.name+"_Obj",true);
            layer_obj_precomp.parentFolder = folder;
           
        var layer_obj = null;

        for(var i=1; i<=comp.numLayers; i++){
            if(comp.layer(i).source && comp.layer(i).source === layer_obj_precomp){
                layer_obj = comp.layer(i);
                break;
            }
        }  

        // ======================================================================================================================================================
        // STEP 3 SHAPE BUILD
        // ======================================================================================================================================================
        statusText = layerName+" : Building Matte Shape...";
        setProgress(25,statusText);
        $.sleep(300);
        
        var shapeChoice = shapeType.selection.text;

        if(shapeChoice === "Circle"){
            statusText = layerName+" : Creating Circle Matte...";
            setProgress(40,statusText);
        } else if(shapeChoice === "Rectangle"){
            statusText = layerName+" : Creating Rectangle Matte...";
            setProgress(40,statusText);
        }
        $.sleep(300);

        // STEP     : CREATE MATTE
        var shape = comp.layers.addShape();
        shape.name = (shapeChoice=="Rectangle")?"RECTANGLE_MATTE":"CIRCLE_MATTE";
        shape.moveBefore(layer_obj);

        var contents = shape.property("ADBE Root Vectors Group");
        var group = contents.addProperty("ADBE Vector Group");
        var groupContents = group.property("ADBE Vectors Group");

        if(shapeChoice === "Circle"){
            var ellipse = groupContents.addProperty("ADBE Vector Shape - Ellipse");
            ellipse.property("Size").setValue([2000,2000]);
        } else if(shapeChoice === "Rectangle"){
            var rect = groupContents.addProperty("ADBE Vector Shape - Rect");
            rect.property("Size").setValue([comp.width, comp.height]);
        }

            groupContents.addProperty("ADBE Vector Graphic - Fill");

        //ANIMATING SHAPE LAYER
        var dir = direction.selection.text;
        if(dir === "Left to Right"){
            var pos = shape.property("Position");
                pos.setValueAtTime(layerStartTime,[(((comp.width/2)-2*(comp.width/2))),comp.height/2]);
                pos.setValueAtTime(layerStartTime+2,[comp.width/2,comp.height/2]);
        }else if(dir === "Right to Left"){
            var pos = shape.property("Position");
                pos.setValueAtTime(layerStartTime,[(((comp.width/2)+2*(comp.width/2))),comp.height/2]);
                pos.setValueAtTime(layerStartTime+2,[comp.width/2,comp.height/2]);
        }else if(dir === "Top to Bottom"){
            var pos = shape.property("Position");
                pos.setValueAtTime(layerStartTime,[comp.width/2,(((comp.height/2)-3*(comp.height/2)))]);
                pos.setValueAtTime(layerStartTime+2,[comp.width/2,comp.height/2]);
        }else if(dir === "Bottom to Top"){
            var pos = shape.property("Position");
                pos.setValueAtTime(layerStartTime,[comp.width/2,(((comp.height/2)+3*(comp.height/2)))]);
                pos.setValueAtTime(layerStartTime+2,[comp.width/2,comp.height/2]);
        }else{
            var scl = shape.property("Scale");
                scl.setValueAtTime(layerStartTime,[0,0]);
                scl.setValueAtTime(layerStartTime+2,[100,100]);
        }  
        
        //STEP : ADDING EFFECTS TO SHAPE LAYER
                    var shape_effect = shape.property("ADBE Effect Parade");

                        // ---------------- TURBULENT DISPLACE ----------------
                        var tur_dis = shape_effect.addProperty("ADBE Turbulent Displace");

                        tur_dis.property("Amount").setValue(200);
                        tur_dis.property("Size").setValue(20);
                        tur_dis.property("Complexity").setValue(10);


                        // ---------------- MOSAIC ----------------
                        var mosaic = shape_effect.addProperty("Mosaic");

                        mosaic.property("Horizontal Blocks").setValue(100);
                        mosaic.property("Vertical Blocks").setValue(50);

                    $.sleep(50);
        statusText = layerName + "Track Matte...";
        setProgress(55,statusText);
        // STEP : APPLY TRACK MATTE (SAFE)
                    try{
                        layer_obj.trackMatteType = TrackMatteType.ALPHA;
                    }catch(e){
                        alert("Track matte error: " + e.toString());
                    }


        // STEP : PRECOMPING LAYER_OBJ AND MATTE LAYER
                    var matte_layer = null;

                    for(var i=1; i<=comp.numLayers; i++){
                        if(comp.layer(i).name === "RECTANGLE_MATTE" || comp.layer(i).name === "CIRCLE_MATTE"){
                            matte_layer = comp.layer(i);
                            break;
                        }
                    }

                    var obj_reveal = null;

                    if(matte_layer && layer_obj){

                        obj_reveal = comp.layers.precompose(
                            [matte_layer.index, layer_obj.index],
                            "Obj_reveal",
                            true
                        
                        );
                        obj_reveal.parentFolder=folder;
                    } else {
                        alert("MISSING LAYERS FOR PRECOMPING");
                        return;
                    }
                    
        $.sleep(50);
        // STEP : FIND NEW PRECOMP LAYER SAFELY
                    var obj_reveal_layer = null;

                    for(var i=1; i<=comp.numLayers; i++){
                        if(comp.layer(i).source && comp.layer(i).source === obj_reveal){
                            obj_reveal_layer = comp.layer(i);
                            break;
                        }
                    }

                    if(!obj_reveal_layer){
                        alert("Could not find final precomp layer");
                        app.endUndoGroup();
                        return;
                    }   
        // ======================================================================================================================================================
        // STEP 4 EFFECTS
        // ======================================================================================================================================================
        setProgress(70,layerName+" :" + "Adding effects...");
        $.sleep(300);

                var effects = obj_reveal_layer.property("ADBE Effect Parade");

                    if(effects){
                        var fillFx = effects.addProperty("ADBE Fill");
                        fillFx.property("Color").setValue([1,1,1]);
                    } else {
                        alert("Effects not available");
                    }

        //Ahead from duplication of obj_reveal
                var obj_1=obj_reveal_layer;
                var obj_2=obj_reveal_layer.duplicate();

                var obj_1Effect = obj_1.property("ADBE Effect Parade");
                var minimax = obj_1Effect.addProperty("ADBE Minimax");
                    minimax.property(1).setValue(1);
                    minimax.property(2).setValue(3);
                    minimax.property(3).setValue(2);
                    minimax.property(5).setValue(false);

                //TRACKMATTE
                    obj_1.trackMatteType = TrackMatteType.ALPHA_INVERTED;
                //PUSHING OBJ_2 3 FRAMES AHEAD
                    var frameDuration = 1 / comp.frameRate;
                        obj_2.startTime += 3 * frameDuration;
        // ======================================================================================================================================================
        // STEP 5 FINALIZE
        // ======================================================================================================================================================
        setProgress(80,layerName+" : Precomping...");
        $.sleep(300);

        //PRECOMPING OBJ1 AND OBJ2
                    if(obj_1 && obj_2){

                        var obj_Scan = comp.layers.precompose(
                            [obj_1.index, obj_2.index],
                            "Obj_Scan",
                            true
                        );
                        obj_Scan.parentFolder=folder;
                    } else {
                        alert("Missing layers for final precomp");
                        return;
                    }

                    var obj_scan_layer = null;

                    for(var i=1; i<=comp.numLayers; i++){
                        if(comp.layer(i).source && comp.layer(i).source === obj_Scan){
                            obj_scan_layer = comp.layer(i);
                            break;
                        }
                    } $.sleep(50);
        setProgress(90,layerName+" : Adding last Effects...");
                    
        //APPLYING CUSTOM EFFECTS TO OBJ_SCAN_LAYER
                    try{
                    var ffxString = "";
                    var ffx = base64Decode(ffxString);
                    var temp = File("~/Desktop/Temp.ffx");
                        temp.encoding="BINARY";
                        temp.open("w");
                        temp.write(ffx);
                        temp.close();
                        obj_scan_layer.applyPreset(temp);
                $.sleep(300);        
                temp.remove();

                }catch(e){
                    alert("Error apply Preset :"+e.toString());
                }
                
        //ADDING OBJ_REVEAL_LAYER TO THE TIMELINE
                    var precompItem = obj_reveal;
                    var obj_reveal2 = comp.layers.add(precompItem);
                        obj_reveal2.moveAfter(obj_scan_layer);
                    obj_scan_layer.blendingMode = BlendingMode.SCREEN; 
                    
                    
                    try{
                        if(obj_scan_layer && obj_reveal2){

                        var MasterControlcx = comp.layers.precompose(
                            [obj_scan_layer.index, obj_reveal2.index],"Animation",
                            true
                        );
                        MasterControlcx.parentFolder=folder;
                    } else {
                        alert("Missing layers for final precomp");
                        return;
                    }
                    }catch(e){
                        alert(e.toString());
                    }
        setProgress(90,layerName+" : Finalizing...");
        $.sleep(300);
        setProgress(100,layerName+" :" + "Done ✔");
       //======================================================================================================================================================== 
       app.endUndoGroup(); 
    };

    return win;
}

var ui = buildUI(thisObj);

if(ui instanceof Window){
    ui.center();
    ui.show();
}

})(this);